def pre(xs):
    """All inputs are valid per the problem specification."""
    return True

def post(xs, result):
    """Verify that result is a correct run-length encoding of xs."""

    # Result must have even length: [v1, c1, v2, c2, ...]
    if len(result) % 2 != 0:
        return False

    # Reconstruct the original list from the encoded result
    reconstructed = []
    for i in range(0, len(result), 2):
        value = result[i]
        count = result[i + 1]
        # Each run must have at least one element
        if count <= 0:
            return False
        # Append 'count' copies of 'value'
        for _ in range(count):
            reconstructed.append(value)

    # The reconstruction must exactly match the input
    if reconstructed != xs:
        return False

    # Consecutive runs must have different values (ensuring maximal runs)
    for i in range(0, len(result) - 2, 2):
        if result[i] == result[i + 2]:
            return False

    return True
